// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public {
        c = new TimelockController(0, new address[](0), new address[](0));
    }

    function testFuzz_property(address account) public {
        bytes32 role = c.TIMELOCK_ADMIN_ROLE();
        bool hasRoleResult = c.hasRole(role, account);
        bool expected = (account == address(this) || account == address(c));
        assertTrue(hasRoleResult == expected);
    }
}
